// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0 && amount <= 100 ether);

        // owner is address(this) (deployer). Fund owner, deposit into c.
        vm.deal(address(this), amount);
        (bool depOk,) = address(c).call{value: amount}("");
        assertTrue(depOk);
        assertTrue(address(c).balance == amount);

        // Owner withdraws everything.
        bool ok = true;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // RULE: if withdrawAll succeeds, the contract must be fully drained.
        assertTrue(!ok || address(c).balance == 0);
    }
}
